import os,json,time
streams=['886','889','890','891','892','893','898','899']
out={'now':time.time(),'streams':{},'state':{}}
for s in streams:
    base=os.path.join('RUNS',s)
    info={'exists':os.path.isdir(base),'runs':[]}
    if os.path.isdir(base):
        dirs=sorted([d for d in os.listdir(base) if os.path.isdir(os.path.join(base,d))], reverse=True)
        for d in dirs[:5]:
            rb=os.path.join(base,d)
            item={'run':d}
            for rel,key in [('RUN_MANIFEST.json','manifest'),('QA/RG_POSTRUN_QA.json','qa'),('LOGS/STUDIO_RUN.log','log')]:
                p=os.path.join(rb,*rel.split('/'))
                if os.path.isfile(p):
                    item[key+'_mtime']=os.path.getmtime(p)
                    item[key+'_size']=os.path.getsize(p)
                    if key in ('manifest','qa'):
                        try:
                            j=json.load(open(p,encoding='utf-8'))
                            if key=='manifest':
                                item[key]={k:j.get(k) for k in ['stream','ok','mode','duration_seconds','audio_policy','algorithm_version']}
                            else:
                                item[key]={k:j.get(k) for k in ['passed','dialogues','xml_count','elapsed_seconds','audio_policy']}
                                item[key]['failed_checks']=[{'name':x.get('name'),'detail':str(x.get('detail'))[:300]} for x in (j.get('checks') or []) if not x.get('ok')]
                        except Exception as e:item[key]={'parse_error':repr(e)}
                    else:
                        try:
                            lines=open(p,encoding='utf-8',errors='replace').read().splitlines()
                            item['log_tail']=lines[-60:]
                        except Exception as e:item['log_error']=repr(e)
            item['files']=[]
            for root,ds,fs in os.walk(rb):
                for n in fs:
                    if n.lower().endswith(('.xml','.json','.zip','.log')):
                        item['files'].append(os.path.relpath(os.path.join(root,n),rb).replace('\\','/'))
                if len(item['files'])>200: break
            info['runs'].append(item)
    out['streams'][s]=info
state='CONTROL/STATE'
if os.path.isdir(state):
    for n in sorted(os.listdir(state)):
        p=os.path.join(state,n)
        try:
            if os.path.isfile(p):
                st=os.stat(p)
                rec={'mtime':st.st_mtime,'size':st.st_size}
                if st.st_size<=1000000:
                    txt=open(p,encoding='utf-8',errors='replace').read()
                    try: rec['json']=json.loads(txt)
                    except Exception: rec['tail']=txt[-12000:]
                out['state'][n]=rec
        except Exception as e: out['state'][n]={'error':repr(e)}
print(json.dumps(out,ensure_ascii=False))
